mapper.select:
SELECT sp.*, cp.name as cate_name, cp.level as cate_level FROM store_product_spu sp INNER JOIN ( WITH RECURSIVE cate_path AS ( SELECT id, parent_id, name, level FROM store_product_cate WHERE id = #{spuCateId}
UNION ALL
SELECT c.id, c.parent_id, c.name, c.level FROM store_product_cate c INNER JOIN cate_path cp ON c.id = cp.parent_id ) SELECT * FROM cate_path ) cp ON sp.cate_id = cp.id WHERE sp.status = 1 LIMIT #{limit}

SELECT sp.id, sp.title, sp.sub_title, sp.market_price, sp.main_image, sp.unit, sp.sort, cp.name as cate_name, cp.level as cate_level, cp.id as cate_id FROM store_product_spu sp INNER JOIN ( WITH RECURSIVE cate_path AS ( SELECT id, parent_id, name, level FROM store_product_cate WHERE id = #{spuCateId} AND status = 1 -- 添加状态过滤
UNION ALL
SELECT c.id, c.parent_id, c.name, c.level FROM store_product_cate c INNER JOIN cate_path cp ON c.parent_id = cp.id WHERE c.status = 1 -- 子分类也需要状态过滤 ) SELECT * FROM cate_path ) cp ON sp.cate_id = cp.id WHERE sp.status = 1 ORDER BY sp.sort DESC, sp.created_time DESC -- 添加排序 LIMIT #{limit}

SELECT sp.*, cp.name as cate_name, cp.level as cate_level FROM store_product_spu sp INNER JOIN ( WITH RECURSIVE cate_path AS ( SELECT id, parent_id, name, level FROM store_product_cate WHERE id = #{cateId} AND status = 1
UNION ALL
SELECT c.id, c.parent_id, c.name, c.level FROM store_product_cate c INNER JOIN cate_path cp ON c.parent_id = cp.id WHERE c.status = 1 ) SELECT * FROM cate_path ) cp ON sp.cate_id = cp.id WHERE 1=1
and sp.status = #{status}
and sp.brand_id=#{brandId}
and sp.store_id=#{storeId}
and sp.title like CONCAT('%', #{title}, '%')
ORDER BY sp.sort DESC, sp.created_time DESC
